package server

import (
	"flame/tools/xsql"

	"github.com/google/uuid"
)

// McpServerConfig maps the mcp_server_configs table inside each tenant schema.
// DDL (already created):
//
//	CREATE TABLE <schema>.mcp_server_configs (
//	    id uuid NOT NULL, -- no default: generated by the program (see NewID)
//	    auth_type varchar(20) NOT NULL,
//	    auth_config jsonb DEFAULT '{}'::jsonb NULL,
//	    is_active bool DEFAULT true NULL,
//	    created_at timestamptz DEFAULT now() NULL,
//	    updated_at timestamptz DEFAULT now() NULL,
//	    CONSTRAINT mcp_server_configs_check CHECK (auth_type IN ('apikey','oauth')),
//	    CONSTRAINT mcp_server_configs_pk PRIMARY KEY (id),
//	    CONSTRAINT mcp_server_configs_unique UNIQUE (auth_type)
//	);
type McpServerConfig struct {
	ID         string     `json:"id"`
	AuthType   string     `json:"auth_type"` // 'apikey' | 'oauth'
	AuthConfig xsql.JSONB `json:"auth_config"`
	IsActive   bool       `json:"is_active"`
	CreatedAt  xsql.Time  `json:"created_at"`
	UpdatedAt  xsql.Time  `json:"updated_at"`
}

// NewID generates a new uuid (the id is supplied by the program, there is no database default).
func (McpServerConfig) NewID() string {
	return uuid.NewString()
}

// OAuthConfig is the auth_config structure of the oauth row (the backend only validates, it never issues tokens).
type OAuthConfig struct {
	Issuer            string `json:"issuer"`             // IdP issuer
	AuthorizeEndpoint string `json:"authorize_endpoint"` // used in WWW-Authenticate on a 401
	JWKSURL           string `json:"jwks_url"`           // JWKS public key location
	Audience          string `json:"audience"`           // expected token audience
	RequiredScope     string `json:"required_scope"`     // expected scope
}
